dashboard.definition:
{
  "title": "Splunk Health Derek+",
  "description": "Traffic-light health for Splunk ingestion, clustering, and host baselines.",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "dataSources": {
    "ds_health_components": {
      "type": "ds.search",
      "name": "Health components",
      "options": {
        "query": "search `exec_health_health_report`\n| eval health_val=lower(coalesce(color, \"unknown\"))\n| stats latest(health_val) as health_val by host, feature\n| eval score=case(health_val=\"green\", 2, health_val=\"yellow\", 1, health_val=\"red\", 0, 1=1, 1)\n| stats min(score) as score, count(eval(score<2)) as unhealthy_hosts by feature\n| eval component=\"instance:\".feature\n| table component, score\n| append [\n    | tstats count as events where index=`exec_health_idx` earliest=-15m latest=now\n    | eval component=\"ingestion_live_15m\", score=if(events>0, 2, 0)\n    | table component, score\n]\n| append [\n    search `exec_health_license_usage` earliest=-8d@d latest=@d\n    | eval GB=b/1024/1024/1024\n    | bin _time span=1d\n    | stats sum(GB) as daily_GB by _time\n    | streamstats window=7 current=f avg(daily_GB) as ma_7d\n    | sort 0 -_time\n    | head 1\n    | eval drop_pct=if(ma_7d>0, round(((ma_7d-daily_GB)/ma_7d)*100, 1), 0)\n    | eval component=\"ingest_vs_7d_ma\", score=case(isnull(ma_7d) OR ma_7d=0, 2, drop_pct>=`exec_health_drop_red_pct`, 0, drop_pct>=`exec_health_drop_yellow_pct`, 1, 1=1, 2)\n    | table component, score\n]\n| append [\n    | tstats latest(_time) as last_data where index=`exec_health_idx` earliest=-24h latest=now by host\n    | eval silent=if((now()-last_data)>`exec_health_silence_sec`, 1, 0)\n    | stats count as hosts, sum(silent) as silent_hosts\n    | eval silent_ratio=if(hosts>0, silent_hosts/hosts, 1)\n    | eval component=\"host_silence\", score=case(hosts=0, 0, silent_hosts=0, 2, silent_ratio>0.2, 0, 1=1, 1)\n    | table component, score\n]\n| eval _color_rank=case(score<=0, 1, score<2, 2, 1=1, 3)",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_overall_health": {
      "type": "ds.chain",
      "name": "Overall health",
      "options": {
        "extend": "ds_health_components",
        "query": "| stats min(score) as overall_score\n| eval overall_status=case(overall_score>=2, \"GREEN\", overall_score>=1, \"YELLOW\", 1=1, \"RED\")\n| eval overall_score=coalesce(overall_score, 0)\n| appendpipe [ stats count | where count=0 | eval overall_score=1, overall_status=\"YELLOW\" ]"
      }
    },
    "ds_license_daily": {
      "type": "ds.search",
      "name": "License GB/day vs 7d MA",
      "options": {
        "query": "search `exec_health_license_usage`\n| bin _time span=1d\n| stats sum(b) as bytes by _time\n| eval daily_GB=bytes/1024/1024/1024\n| streamstats window=7 current=f avg(daily_GB) as ma_7d\n| eval ma_7d=round(ma_7d, 3), daily_GB=round(daily_GB, 3)\n| eval variance_pct=if(ma_7d>0, round(((daily_GB-ma_7d)/ma_7d)*100, 1), 0)\n| eval health_score=case(isnull(ma_7d), 2, daily_GB < ma_7d*(1-`exec_health_drop_red_pct`/100), 0, daily_GB < ma_7d*(1-`exec_health_drop_yellow_pct`/100), 1, 1=1, 2)\n| eval health_label=case(health_score=0, \"RED\", health_score=1, \"YELLOW\", 1=1, \"GREEN\")\n| sort _time",
        "refresh": "15m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-15d@d",
          "latest": "@d"
        }
      }
    },
    "ds_indexer_cluster": {
      "type": "ds.search",
      "name": "Indexer cluster peers",
      "options": {
        "query": "search `exec_health_health_report`\n| eval health_val=lower(coalesce(color, \"unknown\"))\n| stats latest(health_val) as health_val by host, feature\n| eval score=case(health_val=\"green\", 2, health_val=\"yellow\", 1, health_val=\"red\", 0, 1=1, 1)\n| stats min(score) as score, count(eval(score<2)) as unhealthy_hosts by feature\n| stats min(score) as health_score, count as features, count(eval(score<2)) as unhealthy\n| where features>0\n| eval clustering_status=case(health_score>=2, \"GREEN\", health_score>=1, \"YELLOW\", 1=1, \"RED\")\n| eval status_detail=unhealthy.\" / \".features.\" features not green\"\n| appendpipe [\n    stats count\n    | where count=0\n    | eval clustering_status=\"N/A\", health_score=1, status_detail=\"No health.log events\"\n]",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_shc": {
      "type": "ds.search",
      "name": "Search head cluster",
      "options": {
        "query": "search index=_introspection sourcetype=splunk_resource_usage component=Hostwide\n| eval cpu_pct=coalesce('data.cpu_system_pct', 0)+coalesce('data.cpu_user_pct', 0)\n| stats avg(cpu_pct) as avg_cpu, dc(host) as hosts\n| where hosts>0\n| eval avg_cpu=round(avg_cpu, 1)\n| eval health_score=case(avg_cpu>=90, 0, avg_cpu>=75, 1, 1=1, 2)\n| eval shc_status=case(health_score=2, \"GREEN\", health_score=1, \"YELLOW\", 1=1, \"RED\")\n| eval status_detail=avg_cpu.\"% CPU across \".hosts.\" host(s)\"\n| appendpipe [\n    stats count\n    | where count=0\n    | eval shc_status=\"N/A\", health_score=1, status_detail=\"No _introspection data\"\n]",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_silent": {
      "type": "ds.search",
      "name": "Silent hosts",
      "options": {
        "query": "| tstats latest(_time) as last_data where index=`exec_health_idx` by host\n| eval silent=if((now()-last_data)>`exec_health_silence_sec`, 1, 0)\n| stats count as hosts, sum(silent) as silent_hosts\n| fillnull value=0 hosts, silent_hosts\n| eval health_score=case(hosts=0, 0, silent_hosts=0, 2, silent_hosts/hosts>0.2, 0, 1=1, 1)",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_live": {
      "type": "ds.search",
      "name": "Live indexed events 15m",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` earliest=-15m latest=now\n| appendpipe [ stats count | where count=0 | eval events=0 ]\n| eval events_per_sec=round(events/900, 1)",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_top_indexes": {
      "type": "ds.search",
      "name": "Top indexes by GB",
      "options": {
        "query": "search `exec_health_license_usage`\n| eval GB=round(b/1024/1024/1024, 3)\n| stats sum(GB) as GB by idx\n| rename idx as index\n| sort 0 -GB\n| head 20\n| eval _color_rank=3",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_introspection": {
      "type": "ds.search",
      "name": "Hostwide introspection",
      "options": {
        "query": "search index=_introspection sourcetype=splunk_resource_usage component=Hostwide\n| eval cpu_pct=coalesce('data.cpu_system_pct', 0)+coalesce('data.cpu_user_pct', 0)\n| eval mem_used_gb=round(coalesce('data.mem_used', 0)/1024, 2)\n| stats avg(cpu_pct) as avg_cpu_pct, max(cpu_pct) as max_cpu_pct, latest(mem_used_gb) as mem_used_gb by host\n| eval avg_cpu_pct=round(avg_cpu_pct, 1), max_cpu_pct=round(max_cpu_pct, 1)\n| eval _color_rank=case(max_cpu_pct>=90, 1, max_cpu_pct>=75, 2, 1=1, 3)\n| sort 0 -max_cpu_pct",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_host_alerts": {
      "type": "ds.search",
      "name": "Host 2-sigma alerts",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` earliest=-25h@m latest=@m by _time span=15m host\n| timechart span=15m limit=0 useother=f sum(events) as events by host\n| fillnull value=0\n| untable _time host events\n| where _time+900+300 <= now()\n| streamstats window=96 current=f avg(events) as mean_vol stdev(events) as stdev_vol count as samples by host\n| eventstats max(_time) as scored_bucket\n| where _time=scored_bucket\n| eval sigma=`exec_health_sigma`, mean_vol=round(mean_vol, 1), stdev_vol=round(stdev_vol, 1), lower_bound=round(mean_vol-(sigma*stdev_vol), 1)\n| eval baseline_state=case(samples<8, \"WARMUP\", stdev_vol>0 AND events < lower_bound AND mean_vol>10, \"ALERT\", 1=1, \"OK\")\n| eval z_score=if(stdev_vol>0, round((events-mean_vol)/stdev_vol, 2), 0)\n| where baseline_state=\"ALERT\"\n| eval _color_rank=1\n| table host, events, mean_vol, stdev_vol, lower_bound, z_score, baseline_state, _color_rank\n| sort host",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "-25h@m",
          "latest": "@m"
        }
      }
    },
    "ds_topo_overview": {
      "type": "ds.search",
      "name": "Data topology preview",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` by host sourcetype source index\n| rex field=source \"(?i)(?:^|[^A-Za-z])(?<net_proto>tcp|udp)[:/](?<net_port>\\d+)\"\n| eval net_label=case(\n    lower(net_proto)=\"udp\" AND isnotnull(net_port), \"UDP:\".net_port,\n    lower(net_proto)=\"tcp\" AND isnotnull(net_port), \"TCP:\".net_port,\n    1=1, null())\n| eval os_class=case(\n    match(sourcetype, \"(?i)wineventlog|WinHostMon|XmlWinEventLog|^Perfmon|WinRegistry|powershell|^windows:|MSAD:|DhcpSrvLog|^IIS\"), \"Windows\",\n    match(source, \"(?i)WinEventLog|Perfmon:|\\\\\\\\Windows\\\\\\\\\"), \"Windows\",\n    match(sourcetype, \"(?i)^linux_|^osnix|^unix:|^auditd|^journald|^selinux|^secure$|^messages$|^df$|^cpu$|^iostat|^vmstat|^interfaces|^lastlog|^openPorts|^hardware|^netstat|^yum\"), \"Linux\",\n    match(source, \"(?i)^/var/|^/opt/|^/etc/|^/usr/|^/home/\"), \"Linux\",\n    1=1, null())\n| append [\n    search index=_internal source=*metrics.log group=tcpin_connections\n    | eval host=coalesce(sourceHost, hostname)\n    | eval fwd=lower(trim(coalesce(fwdType, \"\")))\n    | eval conn=lower(trim(coalesce(connectionType, \"\")))\n    | eval forwarder_class=case(\n        match(fwd, \"^(uf|lwf)$\"), \"UF\",\n        match(fwd, \"^(full|hf|hwf)$\"), \"HF\",\n        1=1, null())\n    | eval metrics_net=if(isnull(forwarder_class) AND match(conn, \"raw\") AND isnum(coalesce(destPort, dest_port)), \"TCP:\".coalesce(destPort, dest_port), null())\n    | where isnotnull(host) AND (isnotnull(forwarder_class) OR isnotnull(metrics_net))\n    | stats latest(forwarder_class) as forwarder_class, latest(metrics_net) as metrics_net by host\n]\n| append [\n    search index=_internal source=*metrics.log group=udpin_connections\n    | eval host=coalesce(sourceHost, hostname)\n    | eval metrics_net=\"UDP:\".coalesce(destPort, dest_port, port)\n    | where isnotnull(host) AND match(metrics_net, \"^UDP:[0-9]+$\")\n    | stats latest(metrics_net) as metrics_net by host\n]\n| eventstats latest(forwarder_class) as forwarder_class, latest(metrics_net) as metrics_net by host\n| eventstats values(os_class) as os_classes by host\n| where isnotnull(events)\n| eval host_os=case(\n    isnotnull(mvfind(os_classes, \"Windows\")), \"Windows\",\n    isnotnull(mvfind(os_classes, \"Linux\")), \"Linux\",\n    1=1, os_class)\n| eval net_label=coalesce(net_label, metrics_net)\n| eval ingest_path=case(\n    match(sourcetype, \"(?i)httpevent|^aws:|^azure:|^gcp:|^google:|kube:container\"), \"HEC / API / cloud\",\n    match(sourcetype, \"(?i)edge.?processor|ingest.?processor\"), \"Edge / Ingest Processor\",\n    match(sourcetype, \"(?i)sc4s\"), \"SC4S\",\n    forwarder_class=\"HF\", \"HF\",\n    forwarder_class=\"UF\" AND host_os=\"Windows\", \"Windows UF\",\n    forwarder_class=\"UF\", \"Linux UF\",\n    host_os=\"Windows\", \"Windows UF\",\n    isnotnull(net_label), \"Other \".net_label,\n    1=1, \"Other\")\n| stats sum(events) as events by host, ingest_path, index\n| sort 0 -events\n| head 40\n| rename host as data_source, index as splunk_index\n| table data_source, ingest_path, splunk_index",
        "refresh": "5m",
        "refreshType": "delay"
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Splunk Health Derek+\nTraffic lights combine the splunkd health report, live ingestion, 7-day volume baseline, and silent hosts. GREEN = within baseline \u00b7 YELLOW = watch \u00b7 RED = action required.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_overall": {
      "type": "splunk.singlevalue",
      "title": "Overall health",
      "dataSources": {
        "primary": "ds_overall_health"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"overall_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"overall_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_gb": {
      "type": "splunk.singlevalue",
      "title": "Ingestion (complete days)",
      "dataSources": {
        "primary": "ds_license_daily"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"daily_GB\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 2,
        "majorFontSize": 32,
        "unit": " GB",
        "unitPosition": "after",
        "sparklineValues": "> primary | seriesByName(\"daily_GB\")",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "trendDisplay": "percent",
        "trendValue": "> sparklineValues | delta(-2)"
      }
    },
    "viz_var": {
      "type": "splunk.singlevalue",
      "title": "vs 7-day moving average",
      "dataSources": {
        "primary": "ds_license_daily"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"variance_pct\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"health_score\") | lastPoint() | rangeValue(healthColors)",
        "unit": "%",
        "unitPosition": "after",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "numberPrecision": 1,
        "majorFontSize": 32
      },
      "context": {
        "healthColors": [
          {
            "value": "#DC4E41",
            "to": 0.5
          },
          {
            "value": "#F8BE34",
            "from": 0.5,
            "to": 1.5
          },
          {
            "value": "#53A051",
            "from": 1.5
          }
        ]
      }
    },
    "viz_live": {
      "type": "splunk.singlevalue",
      "title": "Indexed events (15m)",
      "dataSources": {
        "primary": "ds_live"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"events\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 0,
        "majorFontSize": 32,
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_idx_cluster": {
      "type": "splunk.singlevalue",
      "title": "Instance health",
      "dataSources": {
        "primary": "ds_indexer_cluster"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"clustering_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"clustering_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_shc": {
      "type": "splunk.singlevalue",
      "title": "Search head load",
      "dataSources": {
        "primary": "ds_shc"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"shc_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"shc_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_silent": {
      "type": "splunk.singlevalue",
      "title": "Silent hosts (>1h no data)",
      "dataSources": {
        "primary": "ds_silent"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"silent_hosts\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"health_score\") | lastPoint() | rangeValue(healthColors)",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 32
      },
      "context": {
        "healthColors": [
          {
            "value": "#DC4E41",
            "to": 0.5
          },
          {
            "value": "#F8BE34",
            "from": 0.5,
            "to": 1.5
          },
          {
            "value": "#53A051",
            "from": 1.5
          }
        ]
      }
    },
    "viz_ingest_chart": {
      "type": "splunk.line",
      "title": "Daily ingestion vs 7-day moving average",
      "dataSources": {
        "primary": "ds_license_daily"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "seriesColors": [
          "#7B56DB",
          "#009CEB",
          "#00CDAF",
          "#DD9900",
          "#FF677B"
        ],
        "legendDisplay": "right",
        "yAxisTitleText": "GB / day",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "markerDisplay": "off"
      }
    },
    "viz_topo": {
      "type": "splunk.linkgraph",
      "title": "Data topology \u2014 sources \u2192 ingest path \u2192 index (open Data Topology for the full map)",
      "dataSources": {
        "primary": "ds_topo_overview"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "fieldOrder": [
          "data_source",
          "ingest_path",
          "splunk_index"
        ],
        "linkColor": "#009CEB",
        "nodeHighlightColor": "#7B56DB",
        "nodeWidth": 170,
        "nodeHeight": 22,
        "nodeSpacingX": 40,
        "nodeSpacingY": 12,
        "resultLimit": 40,
        "showNodeCounts": true,
        "showValueCounts": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "splunk_exec_health",
            "dashboard": "data_topology",
            "newTab": false
          }
        }
      ]
    },
    "viz_top_indexes": {
      "type": "splunk.table",
      "title": "Top indexes by license usage (GB)",
      "dataSources": {
        "primary": "ds_top_indexes"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "count": 15,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "auto",
            "newTab": true
          }
        }
      ]
    },
    "viz_intro": {
      "type": "splunk.table",
      "title": "Indexer/SH resource usage (_introspection)",
      "dataSources": {
        "primary": "ds_introspection"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "count": 15,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
